import org.rabochaya.projects.*;import org.rabochaya.maptests.BmpFixtures;import java.io.*;import java.nio.file.*;import java.lang.reflect.*;import java.util.*;
public final class BmpTests {
 static int n;static void ck(boolean value){n++;if(!value)throw new AssertionError("BMP "+n);}static File write(Path dir,String name,byte[] bytes)throws IOException{Path p=dir.resolve(name);Files.write(p,bytes);return p.toFile();}static int expected(int x,int y){return 0xff000000|((40+x*13+y*17)&255)<<16|((20+x*7+y*11)&255)<<8|((100+x*3+y*5)&255);}static void reject(Path dir,byte[] bytes)throws Exception{File file=write(dir,"bad.bmp",bytes);boolean refused=false;try(BmpRaster raster=new BmpRaster(file)){}catch(IOException e){refused=true;}ck(refused);ck(Arrays.equals(bytes,Files.readAllBytes(file.toPath())));}
 public static void main(String[] args)throws Exception{Path dir=Files.createTempDirectory("bmp-control-");try{
  for(int width:new int[]{1,2,3,4,5,257})for(int bits:new int[]{24,32})for(boolean topDown:new boolean[]{false,true})for(int gap:new int[]{0,7}){int height=3;byte[] bytes=BmpFixtures.image(width,height,bits,topDown,gap);File file=write(dir,"control.bmp",bytes);BmpRaster raster=new BmpRaster(file);try{ck(raster.width==width&&raster.height==height);for(int y=0;y<height;y++)for(int x:new int[]{0,width/2,width-1})ck(raster.pixel(x,y)==expected(x,y));ck(raster.pixel(-1,0)==0&&raster.pixel(width,0)==0&&raster.pixel(0,-1)==0&&raster.pixel(0,height)==0);}finally{raster.close();}ck(Arrays.equals(bytes,Files.readAllBytes(file.toPath())));boolean closed=false;try{raster.pixel(0,0);}catch(IOException e){closed=true;}ck(closed);}
  byte[] base=BmpFixtures.image(3,3,24,false,0);try(BmpRaster raster=new BmpRaster(write(dir,"zero-size.bmp",BmpFixtures.field(base,34,0,4)))){ck(raster.pixel(1,1)==0xff46266c);}
  for(byte[] bad:new byte[][]{Arrays.copyOf(base,53),Arrays.copyOf(base,base.length-1),Arrays.copyOf(base,base.length+1),BmpFixtures.field(base,0,0,2),BmpFixtures.field(base,2,1,4),BmpFixtures.field(base,6,1,2),BmpFixtures.field(base,8,1,2),BmpFixtures.field(base,10,53,4),BmpFixtures.field(base,10,0xffffffffL,4),BmpFixtures.field(base,14,12,4),BmpFixtures.field(base,14,108,4),BmpFixtures.field(base,14,124,4),BmpFixtures.field(base,18,0,4),BmpFixtures.field(base,18,-1,4),BmpFixtures.field(base,18,20001,4),BmpFixtures.field(base,22,0,4),BmpFixtures.field(base,22,0x80000000L,4),BmpFixtures.field(base,26,2,2),BmpFixtures.field(base,28,8,2),BmpFixtures.field(base,28,16,2),BmpFixtures.field(base,30,1,4),BmpFixtures.field(base,30,3,4),BmpFixtures.field(base,34,1,4),BmpFixtures.field(base,46,1,4),BmpFixtures.field(BmpFixtures.field(base,18,20000,4),22,20000,4),BmpFixtures.field(Arrays.copyOf(base,base.length+4),2,base.length+4,4),BmpFixtures.field(Arrays.copyOf(base,base.length-4),2,base.length-4,4)})reject(dir,bad);
  byte[] large=BmpFixtures.image(2560,1792,24,true,3);File file=write(dir,"lru.bmp",large);try(BmpRaster raster=new BmpRaster(file)){for(int y=0;y<7;y++)for(int x=0;x<10;x++)ck(raster.pixel(x*256+100,y*256+100)==expected(x*256+100,y*256+100));Field cache=BmpRaster.class.getDeclaredField("tiles"),size=BmpRaster.class.getDeclaredField("bytes");cache.setAccessible(true);size.setAccessible(true);ck(((Map<?,?>)cache.get(raster)).size()==64&&size.getLong(raster)<=16L*1024*1024);ck(raster.pixel(0,0)==expected(0,0));ck(((Map<?,?>)cache.get(raster)).size()==64);}ck(Arrays.equals(large,Files.readAllBytes(file.toPath())));
  File oversized=dir.resolve("oversized.bmp").toFile();try(RandomAccessFile fileOut=new RandomAccessFile(oversized,"rw")){fileOut.setLength(BmpRaster.MAX_FILE+1);}boolean refused=false;try(BmpRaster raster=new BmpRaster(oversized)){}catch(IOException e){refused=true;}ck(refused&&oversized.length()==BmpRaster.MAX_FILE+1);System.out.println("BMP: "+n+" assertions passed");
 }finally{try(java.util.stream.Stream<Path> paths=Files.walk(dir)){paths.sorted(Comparator.reverseOrder()).forEach(p->{try{Files.delete(p);}catch(IOException e){throw new UncheckedIOException(e);}});}}}
}
